/**
 * Sets the icon of the undo/eraser menu item and updates its enabled state.
 *
 * The icon is explicitly mutated and its alpha reset on every call: drawables loaded from
 * resources share their constant state, so a previous call which greyed the icon out would
 * otherwise leave it transparent forever (see #6162).
 */
private void setUndoIcon(Menu menu, @DrawableRes int iconRes, boolean enabled) {
    MenuItem undoItem = menu.findItem(R.id.action_undo);
    if (undoItem == null) {
        return;
    }
    Drawable icon = ContextCompat.getDrawable(this, iconRes);
    if (icon != null) {
        // mutate() so that changing the alpha does not affect other users of this drawable
        icon = icon.mutate();
        icon.setAlpha(enabled ? Themes.ALPHA_ICON_ENABLED_LIGHT : Themes.ALPHA_ICON_DISABLED_LIGHT);
    }
    undoItem.setIcon(icon);
    undoItem.setEnabled(enabled);
}

